.btn { border-radius: var(--radius-m); border: 1px solid var(--line-strong); background: var(--sheen), var(--surface); height: 40px; color: var(--text); box-shadow: var(--edge-hi), var(--elev-1); cursor: pointer; transition: background .15s ease, border-color .15s ease, transform .15s var(--ease-out), opacity .15s; white-space: nowrap; align-items: center; gap: 0.5rem; padding: 0px 16px; font-size: 0.925rem; font-weight: 600; text-decoration: none; display: inline-flex; }
