.lang__opt[aria-current] { background: var(--sheen), var(--surface-3); color: var(--text); box-shadow: var(--edge-hi), 0 1px 2px #0000004d; }
[data-theme="light"] .tt-sun, :root:not([data-theme="light"]) .tt-moon { display: none; }
.v { --v-max: 1320px; --v-gut: clamp(18px, 4vw, 48px); --v-ring: 0 0 0 1px color-mix(in srgb, var(--text) 9%, transparent); background: radial-gradient(ellipse 60% 42% at 70% -6%, var(--ember-glow), transparent 70%), var(--bg-deep); min-height: 100dvh; }
