.vbrand__mark { width: 28px; height: 28px; color: var(--accent-contrast); background: linear-gradient(150deg, color-mix(in srgb, var(--accent) 88%, white), var(--accent)); box-shadow: 0 2px 10px -2px color-mix(in srgb, var(--accent) 60%, transparent), inset 0 1px 0 #ffffff59; border-radius: 8px; place-items: center; display: grid; }
