.vtop__link[data-tape-hover] { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); }
.v .icon-btn { width: 34px; height: 34px; color: var(--text-2); cursor: pointer; background: 0px 0px; border: 0px; border-radius: 999px; place-items: center; transition: color 0.15s, background-color 0.15s; display: grid; }
.v .icon-btn[data-tape-hover] { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); }
.vbtn { height: 44px; font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; letter-spacing: -0.005em; cursor: pointer; white-space: nowrap; transition: transform .2s var(--ease-out), box-shadow .2s var(--ease-out), background-color .15s, color .15s; border: 0px; border-radius: 999px; justify-content: center; align-items: center; gap: 8px; padding: 0px 20px; font-size: 0.95rem; font-weight: 620; text-decoration: none; display: inline-flex; }
.vbtn--primary { color: var(--accent-contrast); background: linear-gradient(180deg, color-mix(in srgb, var(--accent) 86%, white), var(--accent)); box-shadow: inset 0 1px 0 #ffffff4d, 0 1px 2px #00000040, 0 10px 26px -10px color-mix(in srgb, var(--accent) 75%, transparent); }
.vbtn--primary[data-tape-hover] { box-shadow: inset 0 1px 0 #ffffff4d, 0 2px 4px #00000040, 0 16px 34px -12px color-mix(in srgb, var(--accent) 85%, transparent); transform: translateY(-1px); }
