.vbtn--quiet[data-tape-hover] { background: color-mix(in srgb, var(--text) 11%, transparent); }
.vbtn[data-tape-active] { transform: translateY(0px); }
.vh { max-width: var(--v-max); padding: 0 var(--v-gut) 40px; margin: 0px auto; }
.vh-hero { grid-template-columns: minmax(0px, 0.92fr) minmax(0px, 1.08fr); align-items: center; gap: clamp(28px, 5vw, 80px); padding: clamp(36px, 8vh, 96px) 0px clamp(48px, 9vh, 110px); display: grid; }
