.mc-cv__lock.mc-cv__on { stroke: var(--accent); fill: none; }
.cw { max-width: 920px; padding: clamp(32px, 6vw, 64px) var(--v-gut) 96px; margin: 0px auto; }
.cw__k { font-family: var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-3); margin: 0px 0px 10px; font-size: 12px; }
.cw__t { letter-spacing: -0.03em; color: var(--text); margin: 0px 0px 16px; font-size: clamp(32px, 5vw, 52px); line-height: 1.05; }
.cw__wip { color: var(--text-2); align-items: center; gap: 10px; margin: 0px 0px 22px; font-size: 14px; display: inline-flex; }
.cw__wip span { font-family: var(--font-mono); letter-spacing: 0.1em; color: var(--warn); background: var(--warn-soft); border-radius: 6px; padding: 4px 8px; font-size: 11px; font-weight: 700; }
.cw__lead { color: var(--text-2); margin: 0px 0px 32px; font-size: 19px; line-height: 1.6; }
.cw__etapas { counter-reset: e 0; grid-template-columns: repeat(4, 1fr); gap: 0px; margin: 0px 0px 36px; padding: 0px; list-style: none; display: grid; }
.cw__etapa { color: var(--text-3); flex-direction: column; gap: 4px; padding-top: 22px; font-size: 13px; display: flex; position: relative; }
.cw__etapa::before { content: ""; background: var(--line); height: 2px; position: absolute; top: 6px; left: 14px; right: 0px; }
.cw__etapa:last-child::before { display: none; }
.cw__etapa i { border: 2px solid var(--line-strong); background: var(--bg); border-radius: 50%; width: 14px; height: 14px; position: absolute; top: 0px; left: 0px; }
.cw__etapa b { color: var(--text-2); font-size: 14px; }
.cw__etapa--listo i { background: var(--evt); border-color: var(--evt); }
.cw__etapa--listo::before { background: var(--evt); }
.cw__etapa--borrador i { background: linear-gradient(90deg, var(--warn) 50%, var(--bg) 50%); border-color: var(--warn); }
.cw__grid { grid-template-columns: 1fr 1fr; gap: 14px; display: grid; }
.cw__card { border-radius: var(--radius-m); background: var(--surface); box-shadow: var(--v-ring); padding: 20px; }
.cw__card--wide { grid-column: 1 / -1; }
.cw__card h2 { font-size: 12px; font-family: var(--font-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-3); margin: 0px 0px 10px; font-weight: 600; }
.cw__card p { color: var(--text); margin: 0px; font-size: 16px; line-height: 1.5; }
.cw__q { font-weight: 600; font-size: 19px !important; }
.cw__par { color: var(--text); margin: 0px; padding-left: 18px; line-height: 1.6; }
.cw__fam { flex-wrap: wrap; gap: 8px; margin: 0px; padding: 0px; list-style: none; display: flex; }
.cw__fam li { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); border-radius: 8px; padding: 6px 12px; font-size: 14px; }
.cw__pn { border-top: 1px solid var(--line); justify-content: space-between; align-items: center; gap: 12px; margin-top: 40px; padding-top: 20px; font-size: 14px; display: flex; }
.cw__pn a:not(.vbtn) { color: var(--text-2); text-decoration: none; }
.cw__pn a:not(.vbtn)[data-tape-hover] { color: var(--text); }
@media (width <= 900px) {
  .mc { gap: 48px; }
  .mc-sec__h { grid-template-columns: 1fr; }
  .mc-sec__meta { grid-area: auto / 1; }
  .mc-card--ancha, .mc-piezas { grid-template-columns: 1fr; gap: 14px; }
  .cw__grid { grid-template-columns: 1fr; }
  .cw__etapas { grid-template-columns: repeat(2, 1fr); row-gap: 18px; }
  .cw__pn { text-align: center; flex-direction: column; align-items: stretch; }
}
